/* Sirah events 78-114 (eras 9-11). [Malay, English]. Own-words retelling of Ar-Raheeq al-Makhtum. */
SIRAH.push(
{id:"s78",n:78,e:9,m:1,y:624.2,ah:2,age:54,pl:"badr",sc:"wells",
 w:["Jumaat, 17 Ramadan 2 H (Mac 624)","Friday, 17 Ramadan 2 AH (March 624)"],
 t:["Perang Badar al-Kubra","The Battle of Badr"],
 f:["Sebuah kafilah besar Quraisy pimpinan Abu Sufyan pulang dari Syam. Rasulullah ﷺ keluar dengan kira-kira 313 orang, hanya dua ekor kuda dan tujuh puluh ekor unta, untuk menyekatnya. Abu Sufyan mengubah laluan dan meminta bantuan Makkah. Quraisy keluar dengan kira-kira seribu orang tentera lengkap.\nKafilah terlepas, tetapi tentera Quraisy tetap mara. Baginda bermesyuarat dengan para sahabat. Al-Miqdad dan Sa'd bin Mu'adh menyatakan kesetiaan penuh. Malam sebelum pertempuran, hujan turun menenangkan orang Islam dan mengeraskan tanah di bawah kaki mereka. Atas cadangan al-Hubab bin al-Mundhir, mereka menguasai telaga-telaga Badar.\nRasulullah ﷺ berdoa sepanjang malam: “Ya Allah, jika kumpulan ini binasa, Engkau tidak akan disembah lagi di bumi.” Allah menurunkan para malaikat. Quraisy kalah teruk: tujuh puluh terbunuh, termasuk Abu Jahal, dan tujuh puluh ditawan. Empat belas orang Islam syahid. Allah menamakan hari itu Yaum al-Furqan, hari pemisah antara yang benar dan yang batil.",
   "A large Quraysh caravan led by Abu Sufyan was returning from Syria. The Prophet ﷺ set out with about 313 men, only two horses and seventy camels, to intercept it. Abu Sufyan changed route and called for help from Makkah. Quraysh marched out with about a thousand well-armed men.\nThe caravan escaped, but the Quraysh army kept coming. The Prophet consulted his companions. Al-Miqdad and Sa'd ibn Mu'adh pledged full loyalty. The night before the battle, rain fell, calming the Muslims and firming the ground beneath them. On al-Hubab ibn al-Mundhir's advice, they took control of the wells of Badr.\nThe Prophet ﷺ prayed through the night: “O Allah, if this band perishes, You will not be worshipped on earth.” Allah sent down angels. Quraysh were badly defeated: seventy were killed, Abu Jahl among them, and seventy captured. Fourteen Muslims were martyred. Allah called that day Yawm al-Furqan, the Day of Criterion between truth and falsehood."],
 k:["Pada bulan Ramadan, orang Islam yang sedikit bertemu tentera Quraisy yang jauh lebih ramai di Badar. Nabi ﷺ berdoa bersungguh-sungguh, dan Allah menghantar pertolongan. Orang Islam menang!","In Ramadan, a small group of Muslims faced a much bigger Quraysh army at Badr. The Prophet ﷺ prayed with all his heart, and Allah sent help. The Muslims won!"],
 l:[["Kemenangan datang daripada Allah, bukan daripada jumlah.","Victory comes from Allah, not from numbers."],["Pemimpin yang baik bermesyuarat dan mendengar pandangan.","A good leader consults and listens."],["Doa ialah senjata orang beriman.","Prayer is the believer's weapon."]],
 ay:[{r:"Ali 'Imran 3:123",ar:"وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ",m:["Dan sesungguhnya Allah telah menolong kamu di Badar sedangkan kamu dalam keadaan lemah.","Allah had already given you victory at Badr when you were weak."]},
     {r:"al-Anfal 8:9",ar:"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ",m:["Ingatlah ketika kamu memohon pertolongan kepada Tuhanmu, lalu Dia memperkenankan bagimu.","When you called on your Lord for help, and He answered you."]}],
 hd:[{r:"Sahih Muslim 1763",m:["Umar (r.a.) menceritakan doa Rasulullah ﷺ yang bersungguh-sungguh pada malam Badar hingga kain selendangnya jatuh dari bahu.","'Umar (r.a.) described the Prophet's ﷺ intense prayer on the night of Badr, until his cloak fell from his shoulders."]}],
 p:["abusufyan","abujahal","saad"],s:"The Battle of Badr, p.114|Peperangan Badar al-Kubra"},

{id:"s79",n:79,e:9,y:624.22,ah:2,age:54,pl:"madinah",sc:"book",
 w:["Selepas Badar, 2 H","After Badr, 2 AH"],
 t:["Tawanan Badar: tebusan dengan mengajar","The Badr captives: ransom by teaching"],
 f:["Rasulullah ﷺ bermesyuarat tentang tujuh puluh tawanan. Abu Bakar mencadangkan tebusan kerana mereka masih kaum kerabat dan mungkin beriman kelak. Umar mencadangkan mereka dihukum. Baginda memilih pendapat Abu Bakar, kemudian turun ayat yang menegur pilihan itu tetapi tetap mengizinkan tebusan.\nTebusan ditetapkan antara seribu hingga empat ribu dirham mengikut kemampuan. Tawanan yang tidak mampu tetapi tahu membaca dan menulis diberi tugas mengajar sepuluh kanak-kanak Ansar. Apabila murid-murid itu mahir, guru itu dibebaskan. Ada juga yang dilepaskan tanpa bayaran kerana terlalu miskin.",
   "The Prophet ﷺ consulted about the seventy captives. Abu Bakr advised ransom, since they were kin and might believe one day. 'Umar advised they be punished. He chose Abu Bakr's view; then verses came that rebuked the choice while still allowing ransom.\nRansom was set between one thousand and four thousand dirhams, according to means. Captives who could not pay but could read and write were each given ten children of the Ansar to teach. Once the children were skilled, the teacher was freed. Some very poor captives were released without payment."],
 l:[["Ilmu boleh menjadi harga kebebasan.","Knowledge can be the price of freedom."],["Pendidikan diutamakan sejak awal negara Madinah.","Education was a priority from the very start of the Madinan state."]],
 p:["abubakar","umar"],s:"The Battle of Badr, p.114|Permasalahan tawanan"},

{id:"s80",n:80,e:9,y:624.25,ah:2,age:54,pl:"madinah",sc:"crescent",
 w:["1 Syawal 2 H","1 Shawwal 2 AH"],
 t:["Aidilfitri pertama","The first Eid al-Fitr"],
 f:["Tidak lama selepas kemenangan Badar, umat Islam menyambut Aidilfitri yang pertama. Mereka keluar beramai-ramai, bertakbir dan memuji Allah dengan suara yang kuat, bersyukur atas puasa Ramadan yang pertama dan pertolongan di Badar.\nSebelum itu penduduk Madinah mempunyai dua hari perayaan jahiliah. Rasulullah ﷺ memberitahu bahawa Allah telah menggantikannya dengan dua hari yang lebih baik: Aidilfitri dan Aidiladha.",
   "Soon after the victory at Badr, the Muslims celebrated their first Eid al-Fitr. They went out together, declaring Allah's greatness and praising Him aloud, grateful for their first Ramadan of fasting and the help at Badr.\nBefore this, the people of Madinah had two festival days from the time of ignorance. The Prophet ﷺ told them that Allah had replaced them with two better days: Eid al-Fitr and Eid al-Adha."],
 l:[["Kegembiraan hari raya ialah kesyukuran kepada Allah.","The joy of Eid is gratitude to Allah."]],
 hd:[{r:"Sunan Abi Dawud 1134",m:["Anas (r.a.) meriwayatkan: Allah telah menggantikan dua hari itu dengan yang lebih baik, iaitu hari Adha dan hari Fitri.","Anas (r.a.) narrated: Allah has replaced those two days with better ones, the day of Adha and the day of Fitr."]}],
 s:"The Battle of Badr, p.114|"},

{id:"s81",n:81,e:9,y:624.3,ah:2,age:54,pl:"madinah",sc:"forts",
 w:["Syawal 2 H","Shawwal 2 AH"],
 t:["Bani Qainuqa' melanggar perjanjian","Banu Qaynuqa' break the covenant"],
 f:["Bani Qainuqa' ialah kabilah Yahudi yang paling berani di Madinah, kebanyakannya tukang emas. Selepas Badar mereka mula menunjukkan permusuhan secara terbuka. Rasulullah ﷺ menasihati mereka di pasar, tetapi mereka mencabar: “Jangan tertipu kerana kamu menang menentang orang yang tidak tahu berperang.”\nKemudian seorang wanita Islam dihina di pasar mereka sehingga berlaku pergaduhan yang membawa kepada kematian. Perjanjian pun terbatal. Orang Islam mengepung kubu mereka selama lima belas malam sehingga mereka menyerah. Atas permintaan Abdullah bin Ubai, mereka dihalau keluar dari Madinah dan berpindah ke Syam.",
   "Banu Qaynuqa' were the boldest Jewish tribe in Madinah, mostly goldsmiths. After Badr they began to show open hostility. The Prophet ﷺ warned them in their market, but they taunted him: “Do not be fooled because you beat people who did not know how to fight.”\nThen a Muslim woman was humiliated in their market, leading to a fight in which lives were lost. The covenant was broken. The Muslims besieged their forts for fifteen nights until they surrendered. At 'Abdullah ibn Ubayy's request they were expelled from Madinah, and they moved to Syria."],
 l:[["Perjanjian dijaga selagi pihak lain menjaganya.","A covenant is kept as long as the other side keeps it."],["Kehormatan wanita dipertahankan oleh Islam.","Islam defends the honour of women."]],
 s:"Invasion of Bani Qainuqa', p.147|"},

{id:"s82",n:82,e:9,y:624.45,ah:2,age:54,pl:"najd",sc:"hoof",
 w:["Zulhijjah 2 H hingga awal 3 H","Dhul-Hijjah 2 AH to early 3 AH"],
 t:["Ghazwah as-Sawiq & Dzi Amr","The Sawiq and Dhi Amr expeditions"],
 f:["Selepas Badar, Abu Sufyan bersumpah tidak akan mandi junub sehingga membalas dendam. Beliau menyerang pinggir Madinah dengan dua ratus penunggang, membakar pohon kurma dan membunuh dua orang. Apabila Rasulullah ﷺ mengejar, mereka lari sambil membuang bekalan tepung bijirin (sawiq) supaya lebih ringan. Kerana itu ia dinamakan Ghazwah as-Sawiq.\nTidak lama kemudian, kabilah Ghatafan berkumpul di Dzi Amr untuk menyerang Madinah. Baginda keluar dengan 450 orang, dan mereka bertempiaran lari ke bukit. Ekspedisi-ekspedisi ini menunjukkan bahawa Madinah kini dipertahankan dengan berwaspada.",
   "After Badr, Abu Sufyan swore he would not bathe until he had his revenge. He raided the outskirts of Madinah with two hundred riders, burning palm trees and killing two men. When the Prophet ﷺ gave chase, they fled, dumping their sacks of barley meal (sawiq) to lighten their load. That is why it is called the Sawiq expedition.\nSoon after, the tribe of Ghatafan gathered at Dhi Amr to attack Madinah. He went out with 450 men, and they scattered into the hills. These expeditions showed that Madinah was now watchfully defended."],
 l:[["Berjaga-jaga ialah sebahagian daripada tanggungjawab pemimpin.","Vigilance is part of a leader's duty."]],
 p:["abusufyan"],s:"As-Sawiq Invasion; Dhi Amr Invasion, p.147|"},

{id:"s83",n:83,e:9,y:624.5,ah:2,age:54,pl:"madinah",sc:"family",
 w:["2 H","2 AH"],
 t:["Perkahwinan Fatimah & Ali","Fatimah marries 'Ali"],
 f:["Pada tahun kedua Hijrah, Rasulullah ﷺ mengahwinkan puterinya Fatimah dengan sepupunya Ali bin Abi Talib. Ali tidak berharta. Maharnya ialah baju besinya. Kelengkapan rumah mereka sangat sederhana: tilam kulit yang berisi sabut, bantal, kendi dan batu pengisar.\nMereka dikurniakan anak-anak, antaranya al-Hasan dan al-Husain, yang sangat dikasihi oleh datuk mereka. Rasulullah ﷺ bersabda bahawa Fatimah ialah sebahagian daripada dirinya.",
   "In the second year after the Hijrah, the Prophet ﷺ married his daughter Fatimah to his cousin 'Ali ibn Abi Talib. 'Ali owned little. Her dowry was his coat of armour. Their household was very simple: a leather mattress stuffed with fibre, a pillow, a water jug and a hand mill.\nThey were blessed with children, among them al-Hasan and al-Husayn, whom their grandfather dearly loved. The Prophet ﷺ said that Fatimah was a part of him."],
 l:[["Perkahwinan yang diberkati tidak memerlukan kemewahan.","A blessed marriage does not need luxury."]],
 hd:[{r:"Sahih al-Bukhari 3714",m:["Baginda bersabda: “Fatimah ialah sebahagian daripadaku. Sesiapa yang membuatnya marah, dia telah membuatku marah.”","He said: “Fatimah is a part of me. Whoever angers her angers me.”"]}],
 p:["fatimah","ali"],s:"The Prophet Household, p.311|"},

{id:"s84",n:84,e:9,m:1,y:625.2,ah:3,age:55,pl:"uhud",sc:"uhud",
 w:["Sabtu, 7 Syawal 3 H (Mac 625)","Saturday, 7 Shawwal 3 AH (March 625)"],
 t:["Perang Uhud: pemanah & syahidnya Hamzah","The Battle of Uhud"],
 f:["Quraisy mara dengan tiga ribu tentera untuk membalas kekalahan Badar. Rasulullah ﷺ keluar dengan seribu orang, tetapi Abdullah bin Ubai berpatah balik bersama tiga ratus orang, meninggalkan kira-kira tujuh ratus.\nBaginda menempatkan lima puluh pemanah di bawah Abdullah bin Jubair di atas sebuah bukit kecil, dan berpesan: “Jangan tinggalkan tempat kamu walaupun kamu melihat burung menyambar kami.” Pada mulanya orang Islam menang dan musuh berundur. Melihat harta rampasan, kebanyakan pemanah turun walaupun dilarang oleh ketua mereka. Khalid al-Walid, yang ketika itu di pihak Quraisy, menyerang dari belakang.\nKeadaan menjadi kucar-kacir. Rasulullah ﷺ cedera di wajah dan giginya patah, dan tersebar khabar bahawa Baginda terbunuh. Para sahabat berkumpul mempertahankan Baginda. Tujuh puluh orang Islam syahid, termasuk Hamzah, bapa saudara Baginda, yang dibunuh oleh Wahsyi dan jasadnya dicacatkan. Rasulullah ﷺ sangat berduka atas pemergiannya.",
   "Quraysh marched with three thousand men to avenge Badr. The Prophet ﷺ went out with a thousand, but 'Abdullah ibn Ubayy turned back with three hundred, leaving about seven hundred.\nHe placed fifty archers under 'Abdullah ibn Jubayr on a small hill and told them: “Do not leave your place even if you see birds snatching us.” At first the Muslims were winning and the enemy fell back. Seeing the spoils, most of the archers came down despite their leader's order. Khalid ibn al-Walid, then on the Quraysh side, attacked from behind.\nThe field fell into chaos. The Prophet ﷺ was wounded in the face and a tooth was broken, and a rumour spread that he had been killed. Companions gathered to defend him. Seventy Muslims were martyred, including his uncle Hamzah, who was killed by Wahshi and whose body was mutilated. The Prophet ﷺ grieved deeply for him."],
 k:["Di Bukit Uhud, Nabi ﷺ menyuruh pemanah jangan meninggalkan bukit. Ada yang tidak taat, dan orang Islam menghadapi kesusahan. Kita belajar bahawa mentaati arahan Nabi ﷺ sangat penting.","At Mount Uhud, the Prophet ﷺ told the archers not to leave their hill. Some did not obey, and the Muslims had a very hard time. We learn that obeying the Prophet's ﷺ instructions is very important."],
 l:[["Melanggar arahan pemimpin boleh mengubah kemenangan menjadi kesusahan.","Disobeying the leader's command can turn victory into hardship."],["Harta dunia boleh melalaikan daripada tanggungjawab.","Worldly gain can distract from duty."],["Jangan berputus asa selepas kekalahan.","Do not lose heart after a setback."]],
 ay:[{r:"Ali 'Imran 3:139",ar:"وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ",m:["Janganlah kamu lemah dan janganlah kamu bersedih, padahal kamulah yang paling tinggi jika kamu beriman.","Do not weaken and do not grieve, for you will be uppermost if you are believers."]}],
 hd:[{r:"Sahih al-Bukhari 3039",m:["Pesan Baginda kepada pemanah: “Jika kamu melihat burung menyambar kami, jangan tinggalkan tempat kamu sehingga aku menghantar utusan kepada kamu.”","His order to the archers: “If you see birds snatching us, do not leave your place until I send for you.”"]}],
 p:["hamzah","khalid","musab","abusufyan"],s:"The Battle of Uhud, p.155|Ghazwah Uhud"},

{id:"s85",n:85,e:9,y:625.21,ah:3,age:55,pl:"hamra",sc:"valley",
 w:["8 Syawal 3 H, sehari selepas Uhud","8 Shawwal 3 AH, the day after Uhud"],
 t:["Hamra' al-Asad","Hamra' al-Asad"],
 f:["Pagi selepas Uhud, Rasulullah ﷺ bimbang Quraisy akan berpatah balik untuk menyerang Madinah. Baginda memerintahkan agar hanya mereka yang bertempur di Uhud keluar mengejar musuh, walaupun ramai yang masih cedera.\nMereka berkhemah di Hamra' al-Asad, kira-kira lapan batu dari Madinah, dan menyalakan banyak unggun api. Abu Sufyan yang memang berniat kembali menyerang menjadi gentar dan meneruskan perjalanan ke Makkah. Allah memuji mereka yang menyahut seruan Allah dan Rasul walaupun sudah luka.",
   "The morning after Uhud, the Prophet ﷺ feared Quraysh would turn back to attack Madinah. He ordered that only those who had fought at Uhud should go out after the enemy, even though many were still wounded.\nThey camped at Hamra' al-Asad, about eight miles from Madinah, and lit many fires. Abu Sufyan, who had planned to return and attack, lost his nerve and went on to Makkah. Allah praised those who answered Allah and the Messenger even after being wounded."],
 l:[["Kekuatan semangat boleh menakutkan musuh yang lebih ramai.","Strength of spirit can deter a larger enemy."]],
 ay:[{r:"Ali 'Imran 3:172",ar:"الَّذِينَ اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ مِن بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ",m:["Orang-orang yang menyahut seruan Allah dan Rasul selepas mereka ditimpa luka.","Those who responded to Allah and the Messenger after injury had struck them."]}],
 p:["abusufyan"],s:"Hamra' Al-Asad Invasion, p.155|Peperangan Hamra' al-Asad"},

{id:"s86",n:86,e:9,y:625.6,ah:4,age:56,pl:"najd",sc:"sunset",
 w:["Safar 4 H","Safar 4 AH"],
 t:["Tragedi ar-Raji' & Bi'r Ma'unah","The tragedies of ar-Raji' and Bi'r Ma'unah"],
 f:["Selepas Uhud, beberapa kabilah mengambil kesempatan. Sekumpulan orang dari 'Adal dan al-Qarah meminta guru untuk mengajar Islam. Rasulullah ﷺ menghantar sepuluh orang sahabat, menurut riwayat al-Bukhari. Di ar-Raji', mereka dikhianati: kebanyakannya dibunuh, dan Khubaib bin Adi serta Zaid bin ad-Dathinah dijual ke Makkah lalu dibunuh. Sebelum syahid, Khubaib meminta izin bersolat dua rakaat.\nPada bulan yang sama, Abu Bara' meminta pendakwah untuk penduduk Najd. Baginda menghantar tujuh puluh orang qari, para penghafal al-Quran. Di telaga Ma'unah, mereka dikepung dan dibunuh oleh kabilah-kabilah di bawah 'Amir bin at-Tufail. Hanya seorang dua yang terselamat.\nRasulullah ﷺ sangat berduka dan berdoa dalam qunut selama sebulan terhadap kabilah-kabilah yang mengkhianati itu.",
   "After Uhud, some tribes took advantage. A group from 'Adal and al-Qarah asked for teachers of Islam. The Prophet ﷺ sent ten companions, according to the report in al-Bukhari. At ar-Raji' they were betrayed: most were killed, and Khubayb ibn 'Adi and Zayd ibn ad-Dathinah were sold to Makkah and put to death. Before he died, Khubayb asked to pray two rak'ahs.\nIn the same month Abu Bara' asked for callers to teach the people of Najd. He sent seventy reciters who knew the Quran by heart. At the well of Ma'unah they were surrounded and killed by tribes under 'Amir ibn at-Tufayl. Only one or two survived.\nThe Prophet ﷺ grieved deeply and supplicated in the qunut for a month against the tribes who betrayed them."],
 l:[["Para pendakwah mengorbankan nyawa untuk menyampaikan al-Quran.","The callers gave their lives to carry the Quran."],["Khubaib memulakan sunnah solat dua rakaat sebelum dihukum bunuh.","Khubayb began the practice of praying two rak'ahs before execution."]],
 o:["Ada riwayat yang menyebut enam orang dihantar ke ar-Raji'.","Some reports say six were sent to ar-Raji'."],
 s:"The Event of Ar-Raji'; The Tragedy of Ma'una Well, p.186|Tragedi Bi'r Ma'unah"},

{id:"s87",n:87,e:9,y:625.65,ah:4,age:56,pl:"madinah",sc:"forts",
 w:["Rabiulawal 4 H (Ogos 625)","Rabi' al-Awwal 4 AH (August 625)"],
 t:["Bani an-Nadhir diusir","Banu an-Nadir are expelled"],
 f:["Rasulullah ﷺ pergi ke perkampungan Bani an-Nadhir untuk meminta mereka membantu membayar diat, mengikut perjanjian. Mereka menyambut dengan baik di luar, tetapi secara rahsia merancang menjatuhkan batu dari atas dinding ke atas Baginda. Jibril memberitahu Baginda, dan Baginda bangun pulang ke Madinah.\nBaginda memberi mereka tempoh sepuluh hari untuk keluar. Abdullah bin Ubai menjanjikan bantuan, maka mereka enggan. Orang Islam mengepung kubu mereka selama enam malam, menurut riwayat yang dipilih, sehingga mereka menyerah. Mereka dibenarkan keluar membawa apa yang dapat dibawa oleh unta, kecuali senjata, dan sebahagian besar berpindah ke Khaibar. Surah al-Hasyr turun tentang peristiwa ini.",
   "The Prophet ﷺ went to Banu an-Nadir to ask for their share of a blood payment, as their treaty required. They welcomed him outwardly, but secretly plotted to drop a stone on him from a wall. Jibril told him, and he got up and returned to Madinah.\nHe gave them ten days to leave. 'Abdullah ibn Ubayy promised help, so they refused. The Muslims besieged their forts for six nights, by the preferred report, until they surrendered. They were allowed to leave with whatever their camels could carry, except weapons, and most moved to Khaibar. Surah al-Hashr was revealed about this event."],
 l:[["Pengkhianatan memutuskan perjanjian.","Treachery ends a treaty."],["Janji golongan munafik tidak boleh dipercayai.","The promises of hypocrites cannot be relied on."]],
 ay:[{r:"al-Hasyr 59:2",ar:"هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِن دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ",m:["Dialah yang mengeluarkan orang kafir dalam kalangan Ahli Kitab dari kampung halaman mereka pada pengusiran yang pertama.","It is He who expelled the disbelievers among the People of the Book from their homes at the first gathering."]}],
 s:"Bani An-Nadeer Invasion, p.186|Peperangan Banu al-Nadir"},

{id:"s88",n:88,e:9,y:626.1,ah:4,age:56,pl:"badr",sc:"wells",
 w:["Syaaban 4 H (Januari 626)","Sha'ban 4 AH (January 626)"],
 t:["Badar kedua","Badr the Second"],
 f:["Selepas Uhud, Abu Sufyan berjanji untuk bertemu lagi di Badar pada tahun berikutnya. Ketika tiba masanya, Rasulullah ﷺ keluar dengan seribu lima ratus orang dan sepuluh ekor kuda, lalu menunggu di Badar selama lapan hari.\nAbu Sufyan keluar dengan dua ribu orang, tetapi beralasan tahun itu kemarau dan berpatah balik. Orang Islam berniaga di pasar Badar dan pulang dengan keuntungan. Maruah orang Islam yang terjejas di Uhud kini pulih.",
   "After Uhud, Abu Sufyan had promised to meet again at Badr the following year. When the time came, the Prophet ﷺ went out with fifteen hundred men and ten horses, and waited at Badr for eight days.\nAbu Sufyan set out with two thousand men, but made the drought his excuse and turned back. The Muslims traded at the Badr market and came home with a profit. The standing of the Muslims, shaken at Uhud, was restored."],
 l:[["Menepati janji menunjukkan keberanian.","Keeping one's word shows courage."]],
 p:["abusufyan"],s:"The Invasion of Badr, the Second, p.186|Peperangan Badar kedua"},

{id:"s89",n:89,e:9,y:626.6,ah:5,age:57,pl:"dumah",sc:"caravan",
 w:["Rabiulawal 5 H","Rabi' al-Awwal 5 AH"],
 t:["Daumatul Jandal","Dumat al-Jandal"],
 f:["Rasulullah ﷺ mendapat berita bahawa kabilah-kabilah di Daumatul Jandal, berhampiran sempadan Syam, merompak kafilah dan berhimpun untuk menyerang Madinah. Baginda keluar dengan seribu orang, berjalan pada waktu malam dan bersembunyi pada waktu siang.\nApabila mereka tiba, musuh telah lari bertempiaran meninggalkan ternakan mereka. Baginda tinggal beberapa hari dan menghantar pasukan ke sekitar, tetapi tiada pertempuran. Ekspedisi ini menunjukkan jangkauan kuasa Madinah sampai ke utara Semenanjung Arab.",
   "The Prophet ﷺ learned that tribes at Dumat al-Jandal, near the border of Syria, were raiding caravans and gathering to attack Madinah. He set out with a thousand men, marching by night and hiding by day.\nWhen they arrived, the enemy had scattered, leaving their herds behind. He stayed a few days and sent units around the area, but there was no fighting. The expedition showed that Madinah's reach now extended to the north of Arabia."],
 l:[["Menghalang bahaya sebelum ia sampai.","Stop danger before it arrives."]],
 s:"The Invasion of Doumat Al-Jandal, p.186|Peperangan Daumah al-Jandal"},

{id:"s90",n:90,e:9,m:1,y:627.1,ah:5,age:57,pl:"madinah",sc:"trench",
 w:["Syawal 5 H (627)","Shawwal 5 AH (627)"],
 t:["Perang Ahzab (Khandaq)","The Battle of the Confederates (the Trench)"],
 f:["Pemimpin Bani an-Nadhir yang diusir ke Khaibar memujuk Quraisy, Ghatafan dan kabilah-kabilah lain untuk bersatu menyerang Madinah. Satu pakatan seramai kira-kira sepuluh ribu orang terbentuk, lebih ramai daripada seluruh penduduk Madinah.\nSalman al-Farisi mencadangkan sebuah parit digali di bahagian utara Madinah yang terbuka. Rasulullah ﷺ sendiri menggali bersama tiga ribu orang sahabat dalam kesejukan dan kelaparan, sambil bersyair memohon keampunan untuk Ansar dan Muhajirin. Apabila tentera bersekutu tiba, mereka terkejut melihat parit yang tidak pernah dikenali orang Arab.\nKepungan berlangsung lebih sebulan. Bani Quraizah di dalam Madinah pula membatalkan perjanjian. Keadaan sangat genting. Kemudian Nu'aim bin Mas'ud, yang baru memeluk Islam secara rahsia, memecah-belahkan kepercayaan antara musuh. Allah menghantar angin sejuk yang kencang pada suatu malam, menerbangkan khemah dan memadamkan api mereka. Tentera bersekutu pun berundur. Baginda bersabda: “Sekarang kita yang akan menyerang mereka, dan mereka tidak akan menyerang kita lagi.”",
   "Leaders of Banu an-Nadir, exiled to Khaibar, persuaded Quraysh, Ghatafan and other tribes to unite against Madinah. An alliance of about ten thousand men formed, more than all the people of Madinah.\nSalman al-Farisi suggested digging a trench along the open northern side of Madinah. The Prophet ﷺ dug himself alongside three thousand companions, in cold and hunger, chanting prayers of forgiveness for the Ansar and the Muhajirin. When the confederates arrived, they were stunned by a trench, something the Arabs had never seen.\nThe siege lasted over a month. Banu Qurayzah inside Madinah broke their treaty. Things were desperate. Then Nu'aym ibn Mas'ud, who had secretly become Muslim, sowed distrust among the enemy. Allah sent a fierce cold wind one night, tearing down their tents and putting out their fires. The confederates withdrew. He said: “Now we will go to them, and they will not come against us again.”"],
 k:["Ramai musuh datang untuk menyerang Madinah. Salman al-Farisi mencadangkan supaya parit yang dalam digali. Nabi ﷺ menggali bersama para sahabat. Akhirnya Allah menghantar angin kencang dan musuh pulang.","A huge army came to attack Madinah. Salman al-Farisi suggested digging a deep trench. The Prophet ﷺ dug alongside his companions. In the end Allah sent a strong wind and the enemy went home."],
 l:[["Idea yang baik diterima walaupun datang dari orang asing.","A good idea is welcome even from a newcomer."],["Pemimpin berkongsi kesusahan bersama rakyat.","A leader shares hardship with his people."],["Pertolongan Allah datang ketika keadaan paling genting.","Allah's help comes at the hardest moment."]],
 ay:[{r:"al-Ahzab 33:9",ar:"يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا",m:["Wahai orang beriman, ingatlah nikmat Allah kepada kamu ketika tentera-tentera datang kepadamu, lalu Kami hantarkan kepada mereka angin dan tentera yang tidak dapat kamu lihat.","O you who believe, remember Allah's favour to you when armies came against you, and We sent against them a wind and armies you did not see."]}],
 hd:[{r:"Sahih al-Bukhari 2834",m:["Ketika menggali parit, Baginda bersyair: “Ya Allah, tiada kehidupan melainkan kehidupan akhirat, maka ampunilah Ansar dan Muhajirin.”","While digging the trench, he chanted: “O Allah, there is no life but the life of the Hereafter, so forgive the Ansar and the Muhajirin.”"]}],
 p:["salman","abusufyan","saad"],s:"Al-Ahzab (the Confederates) Invasion, p.195|"},

{id:"s91",n:91,e:9,y:627.2,ah:5,age:57,pl:"madinah",sc:"forts",
 w:["Zulkaedah 5 H","Dhul-Qa'dah 5 AH"],
 t:["Bani Quraizah","Banu Qurayzah"],
 f:["Pada hari tentera bersekutu berundur, Jibril datang dan memerintahkan Rasulullah ﷺ menuju Bani Quraizah, yang mengkhianati perjanjian ketika Madinah paling terancam. Baginda bersabda: “Jangan seorang pun solat Asar melainkan di perkampungan Bani Quraizah.”\nOrang Islam mengepung mereka selama dua puluh lima malam sehingga mereka menyerah. Mereka meminta agar Sa'd bin Mu'adh, ketua Aus dan sekutu lama mereka, menjadi hakim. Sa'd, yang cedera parah di Khandaq, menghukum mengikut hukuman pengkhianatan dalam peperangan pada masa itu: lelaki yang berperang dihukum bunuh, dan wanita serta kanak-kanak ditawan. Ar-Raheeq menyebut antara enam hingga tujuh ratus orang dihukum. Tidak lama selepas itu, Sa'd wafat akibat lukanya.",
   "On the day the confederates withdrew, Jibril came and ordered the Prophet ﷺ to march on Banu Qurayzah, who had betrayed their treaty when Madinah was in greatest danger. He said: “None of you should pray 'Asr except at Banu Qurayzah.”\nThe Muslims besieged them for twenty-five nights until they surrendered. They asked that Sa'd ibn Mu'adh, chief of Aws and their old ally, be their judge. Sa'd, gravely wounded at the Trench, judged by the wartime penalty for treason in that age: the fighting men were put to death, and the women and children were taken captive. Ar-Raheeq gives between six and seven hundred who were executed. Soon after, Sa'd died of his wound."],
 l:[["Mengkhianati negara ketika perang ialah jenayah yang paling berat.","Betraying one's state in wartime is the gravest of crimes."],["Mereka sendiri memilih hakim mereka.","They chose their own judge."]],
 hd:[{r:"Sahih al-Bukhari 946",m:["Baginda bersabda pada hari Ahzab: “Jangan seorang pun solat Asar melainkan di Bani Quraizah.”","He said on the day of the Confederates: “None of you should pray 'Asr except at Banu Qurayzah.”"]}],
 p:["saad"],s:"Invading Banu Quraiza, p.201|"},

{id:"s92",n:92,e:10,y:627.9,ah:6,age:58,pl:"muraisi",sc:"tent2",
 w:["Syaaban 6 H","Sha'ban 6 AH"],
 t:["Bani al-Mustaliq & peristiwa Ifk","Banu al-Mustaliq and the slander"],
 f:["Bani al-Mustaliq berkumpul untuk menyerang Madinah. Rasulullah ﷺ mendahului mereka di telaga al-Muraisi' dan mengalahkan mereka. Baginda kemudian berkahwin dengan Juwairiyah binti al-Harith, puteri ketua mereka. Para sahabat lalu membebaskan seratus keluarga tawanan kerana mereka kini kerabat Rasulullah ﷺ.\nDalam perjalanan pulang, Aisyah tertinggal kerana mencari kalungnya yang hilang. Safwan bin al-Mu'attal menemuinya dan membawanya ke rombongan dengan menuntun untanya. Golongan munafik di bawah Abdullah bin Ubai menyebarkan fitnah tentang beliau. Selama sebulan Madinah gempar, dan Aisyah jatuh sakit serta menangis tanpa henti.\nAkhirnya Allah menurunkan ayat-ayat Surah an-Nur yang membersihkan nama Aisyah, dan menetapkan hukuman bagi orang yang menuduh tanpa empat saksi.",
   "Banu al-Mustaliq gathered to attack Madinah. The Prophet ﷺ reached them first at the well of al-Muraisi' and defeated them. He then married Juwayriyah bint al-Harith, their chief's daughter. The companions freed a hundred families of captives, since they were now the Prophet's ﷺ in-laws.\nOn the way home, 'A'ishah was left behind while searching for a lost necklace. Safwan ibn al-Mu'attal found her and brought her to the army, leading her camel on foot. The hypocrites under 'Abdullah ibn Ubayy spread slander about her. For a month Madinah was in turmoil, and 'A'ishah fell ill and wept without end.\nThen Allah revealed verses of Surah an-Nur declaring her innocence, and set a penalty for anyone who accuses without four witnesses."],
 l:[["Jangan menyebarkan berita yang belum pasti.","Do not spread news that is not certain."],["Allah membela orang yang difitnah.","Allah defends the slandered."]],
 ay:[{r:"an-Nur 24:11",ar:"إِنَّ الَّذِينَ جَاءُوا بِالْإِفْكِ عُصْبَةٌ مِّنكُمْ",m:["Sesungguhnya orang yang membawa berita bohong itu ialah segolongan daripada kamu.","Indeed, those who came with the slander are a group among you."]}],
 hd:[{r:"Sahih al-Bukhari 4141",m:["Aisyah (r.a.) sendiri menceritakan peristiwa Ifk dengan panjang lebar.","'A'ishah (r.a.) herself narrated the slander affair in full."]}],
 o:["Sebahagian ahli sejarah meletakkan peperangan ini pada tahun 5 H.","Some historians place this campaign in 5 AH."],
 p:["aisyah"],s:"Bani Al-Mustaliq (Muraisi') Ghazwah, p.207|Peperangan Banu al-Mustalaq atau peperangan al-Muraisi'"},

{id:"s93",n:93,e:10,m:1,y:628.2,ah:6,age:58,pl:"hudaibiyah",sc:"tree",
 w:["Zulkaedah 6 H (Mac 628)","Dhul-Qa'dah 6 AH (March 628)"],
 t:["Bai'atur Ridwan & Perjanjian Hudaibiyah","The Pledge of Ridwan and the Treaty of Hudaibiyah"],
 f:["Rasulullah ﷺ bermimpi menunaikan umrah, lalu berangkat dengan kira-kira 1,400 sahabat dalam keadaan ihram, membawa binatang korban, tanpa niat berperang. Quraisy menghalang mereka. Baginda berhenti di Hudaibiyah dan menghantar Uthman bin Affan sebagai utusan.\nApabila tersebar khabar Uthman dibunuh, Baginda mengajak para sahabat berbai'ah di bawah sebatang pohon untuk tidak lari. Allah meredai mereka, dan ia dikenali sebagai Bai'atur Ridwan. Uthman kemudian kembali selamat.\nQuraisy menghantar Suhail bin Amr untuk berunding. Syaratnya kelihatan berat: orang Islam pulang tahun itu dan datang umrah tahun hadapan selama tiga hari; gencatan senjata sepuluh tahun; orang Quraisy yang lari ke Madinah dipulangkan, tetapi tidak sebaliknya. Para sahabat sangat sedih, dan Umar bertanya mengapa mereka menerima kehinaan. Atas nasihat Ummu Salamah, Baginda keluar menyembelih korban dan bercukur, lalu semua sahabat mengikut.\nDalam perjalanan pulang, Surah al-Fath turun dan menamakan perjanjian ini ‘kemenangan yang nyata’.",
   "The Prophet ﷺ dreamt that he performed 'umrah, and set out with about 1,400 companions in ihram, bringing sacrificial animals, with no intention of fighting. Quraysh barred their way. He stopped at Hudaibiyah and sent 'Uthman ibn 'Affan as envoy.\nWhen a rumour spread that 'Uthman had been killed, he called the companions to pledge under a tree that they would not flee. Allah was pleased with them, and it became known as the Pledge of Ridwan. 'Uthman later returned safely.\nQuraysh sent Suhayl ibn 'Amr to negotiate. The terms seemed harsh: the Muslims would go home that year and come for 'umrah the next year for three days; a ten-year truce; any Qurayshi who fled to Madinah would be returned, but not the reverse. The companions were deeply upset, and 'Umar asked why they should accept humiliation. On Umm Salamah's advice he went out, sacrificed and shaved his head, and everyone followed.\nOn the way home Surah al-Fath was revealed, calling this treaty ‘a clear victory’."],
 k:["Nabi ﷺ dan para sahabat mahu menunaikan umrah, tetapi dihalang. Para sahabat berjanji setia kepada Nabi ﷺ di bawah sebatang pokok. Kemudian satu perjanjian damai dibuat, dan Allah menyebutnya satu kemenangan.","The Prophet ﷺ and his companions wanted to perform 'umrah, but were stopped. The companions pledged loyalty to the Prophet ﷺ under a tree. Then a peace treaty was made, and Allah called it a victory."],
 l:[["Perdamaian kadangkala lebih besar kemenangannya daripada peperangan.","Peace is sometimes a bigger victory than war."],["Kesabaran terhadap perkara yang kelihatan pahit membawa kebaikan.","Patience with what seems bitter brings good."],["Nasihat seorang isteri yang bijak menyelesaikan masalah besar.","A wise wife's advice solved a great problem."]],
 ay:[{kid:1,r:"al-Fath 48:1",ar:"إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا",m:["Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata.","Indeed, We have given you a clear victory."]},
     {r:"al-Fath 48:18",ar:"لَّقَدْ رَضِيَ اللَّهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ الشَّجَرَةِ",m:["Sesungguhnya Allah telah meredai orang beriman ketika mereka berbai'ah kepadamu di bawah pohon.","Allah was pleased with the believers when they pledged to you under the tree."]}],
 hd:[{r:"Sahih al-Bukhari 2731",m:["Kisah penuh Perjanjian Hudaibiyah diriwayatkan oleh al-Miswar bin Makhramah dan Marwan.","The full story of Hudaibiyah is narrated by al-Miswar ibn Makhramah and Marwan."]}],
 p:["uthman","umar"],s:"Al-Hudaibiyah Treaty, p.213|Perjanjian al-Hudaibiyyah"},

{id:"s94",n:94,e:10,m:1,y:628.4,ah:7,age:59,pl:"madinah",sc:"letters",
 w:["Akhir 6 H hingga awal 7 H","Late 6 AH to early 7 AH"],
 t:["Surat kepada raja-raja","Letters to the kings"],
 f:["Selepas Hudaibiyah membawa keamanan, Rasulullah ﷺ mengutus surat kepada raja-raja dan pemerintah, mengajak mereka kepada Islam. Baginda membuat sebentuk cincin perak dengan ukiran ‘Muhammad Rasul Allah’ sebagai cop.\nSurat dihantar kepada an-Najasyi di Habsyah, al-Muqauqis di Mesir, Kisra di Parsi, Heraclius (Hiraql) di Rom, al-Mundhir bin Sawa di Bahrain, Haudhah bin Ali di Yamamah, al-Harith al-Ghassani di Damsyik, dan dua raja Oman. An-Najasyi menerima dengan hormat. Al-Muqauqis membalas dengan hadiah, termasuk Mariyah. Heraclius bertanya Abu Sufyan tentang Baginda dan hampir menerima, tetapi takut kehilangan takhta. Kisra pula mengoyakkan surat itu, lalu Baginda berdoa agar kerajaannya terkoyak.",
   "With the peace brought by Hudaibiyah, the Prophet ﷺ sent letters to kings and rulers inviting them to Islam. He had a silver ring made, engraved ‘Muhammad Rasul Allah’, to use as a seal.\nLetters went to the Negus in Abyssinia, al-Muqawqis in Egypt, Chosroes in Persia, Heraclius in Rome, al-Mundhir ibn Sawa in Bahrain, Hawdhah ibn 'Ali in Yamamah, al-Harith al-Ghassani in Damascus, and the two kings of Oman. The Negus received his with honour. Al-Muqawqis replied with gifts, including Mariyah. Heraclius questioned Abu Sufyan about him and nearly accepted, but feared losing his throne. Chosroes tore up the letter, and the Prophet prayed that his kingdom would be torn apart."],
 k:["Nabi ﷺ menghantar surat kepada raja-raja di negeri yang jauh, mengajak mereka menyembah Allah. Ada raja yang menghormati surat itu, dan ada yang tidak. Islam mula dikenali di seluruh dunia.","The Prophet ﷺ sent letters to kings in faraway lands, inviting them to worship Allah. Some kings respected the letters, and some did not. Islam began to be known around the world."],
 l:[["Risalah Islam untuk seluruh manusia, bukan bangsa Arab sahaja.","The message of Islam is for all people, not only the Arabs."],["Dakwah disampaikan dengan surat yang sopan dan jelas.","The call was made through polite and clear letters."]],
 hd:[{r:"Sahih al-Bukhari 7",m:["Abu Sufyan menceritakan soal jawabnya dengan Heraclius tentang Rasulullah ﷺ.","Abu Sufyan related his questioning by Heraclius about the Prophet ﷺ."]}],
 p:["najasyi","abusufyan"],s:"The Prophet's Plans to Spread the Message of Islam beyond Arabia, p.221|Perutusan kepada raja-raja dan gabenor-gabenor"},

{id:"s95",n:95,e:10,m:1,y:628.5,ah:7,age:59,pl:"khaibar",sc:"forts",
 w:["Muharram 7 H (628)","Muharram 7 AH (628)"],
 t:["Pembukaan Khaibar","The conquest of Khaibar"],
 f:["Khaibar, kira-kira 160 kilometer di utara Madinah, menjadi pusat pakatan menentang Islam selepas Bani an-Nadhir berpindah ke sana. Merekalah yang menghasut tentera Ahzab. Rasulullah ﷺ keluar dengan 1,400 orang, iaitu mereka yang hadir di Hudaibiyah sahaja.\nKhaibar mempunyai lapan kubu yang kukuh. Selepas beberapa hari, Baginda bersabda: “Esok aku akan menyerahkan panji kepada seorang lelaki yang mencintai Allah dan Rasul-Nya, dan dicintai oleh Allah dan Rasul-Nya.” Panji itu diserahkan kepada Ali, dan kubu-kubu dibuka satu demi satu.\nPenduduk Khaibar meminta untuk terus mengusahakan tanah mereka. Baginda bersetuju dengan syarat separuh hasil diserahkan kepada orang Islam. Baginda berkahwin dengan Safiyyah binti Huyai selepas beliau memeluk Islam. Di Khaibar juga, seorang wanita Yahudi menghidangkan daging kambing beracun. Baginda meludahkannya, tetapi seorang sahabat, Bisyr bin al-Bara', wafat kerananya.",
   "Khaibar, about 160 kilometres north of Madinah, had become the centre of plots against Islam after Banu an-Nadir moved there. It was they who stirred up the Confederates. The Prophet ﷺ set out with 1,400 men, only those who had been at Hudaibiyah.\nKhaibar had eight strong forts. After some days he said: “Tomorrow I will give the banner to a man who loves Allah and His Messenger, and whom Allah and His Messenger love.” The banner went to 'Ali, and the forts fell one after another.\nThe people of Khaibar asked to keep farming their land. He agreed, on condition that half the harvest went to the Muslims. He married Safiyyah bint Huyayy after she accepted Islam. Also at Khaibar, a Jewish woman served poisoned mutton. He spat it out, but a companion, Bishr ibn al-Bara', died of it."],
 k:["Nabi ﷺ dan para sahabat pergi ke Khaibar, yang mempunyai banyak kubu yang kuat. Nabi ﷺ menyerahkan bendera kepada Ali, dan dengan pertolongan Allah kubu-kubu itu dibuka.","The Prophet ﷺ and his companions went to Khaibar, which had many strong forts. The Prophet ﷺ gave the banner to 'Ali, and with Allah's help the forts were opened."],
 l:[["Kasih kepada Allah dan Rasul ialah kemuliaan tertinggi.","Love of Allah and His Messenger is the highest honour."],["Islam berlaku adil kepada penduduk yang kalah.","Islam dealt fairly with the defeated."]],
 hd:[{r:"Sahih al-Bukhari 3701",m:["Sahl bin Sa'd (r.a.) meriwayatkan sabda Baginda tentang panji di Khaibar yang diserahkan kepada Ali.","Sahl ibn Sa'd (r.a.) narrated his words about the banner at Khaibar, which was given to 'Ali."]}],
 p:["ali"],s:"The Conquest of Khaibar, p.233|Peperangan al-Khaibar dan Wadi al-Qura"},

{id:"s96",n:96,e:10,y:628.52,ah:7,age:59,pl:"khaibar",sc:"ship",
 w:["7 H, ketika di Khaibar","7 AH, at Khaibar"],
 t:["Ja'far pulang dari Habsyah","Ja'far returns from Abyssinia"],
 f:["Ketika Rasulullah ﷺ masih di Khaibar, Ja'far bin Abi Talib dan baki muhajirin Habsyah tiba setelah lebih sepuluh tahun di perantauan. Mereka diiringi oleh Abu Musa al-Asy'ari dan kaumnya dari Yaman. Baginda memeluk Ja'far, mencium dahinya dan bersabda: “Aku tidak tahu yang mana lebih menggembirakanku: pembukaan Khaibar atau kedatangan Ja'far.”\nAbu Hurairah juga memeluk Islam dan tiba sekitar masa ini. Beliau kemudiannya menjadi perawi hadith yang paling banyak meriwayatkan.",
   "While the Prophet ﷺ was still at Khaibar, Ja'far ibn Abi Talib and the last of the Abyssinian emigrants arrived after more than ten years away. With them were Abu Musa al-Ash'ari and his people from Yemen. He embraced Ja'far, kissed his forehead and said: “I do not know which makes me happier: the conquest of Khaibar or the arrival of Ja'far.”\nAbu Hurayrah also accepted Islam and arrived around this time. He would become the most prolific narrator of hadith."],
 l:[["Pertemuan semula dengan saudara seagama ialah satu kegembiraan.","Reunion with brothers in faith is a true joy."]],
 p:["jafar"],s:"The Conquest of Khaibar, p.233|Peperangan al-Khaibar dan Wadi al-Qura"},

{id:"s97",n:97,e:10,y:628.7,ah:7,age:59,pl:"najd",sc:"valley",
 w:["7 H (pendapat Ar-Raheeq)","7 AH (Ar-Raheeq's view)"],
 t:["Dzat ar-Riqa': solat khauf","Dhat ar-Riqa': the prayer of fear"],
 f:["Rasulullah ﷺ keluar ke Najd untuk menghadapi kabilah-kabilah Ghatafan yang berhimpun. Perjalanan sangat sukar: enam orang bergilir-gilir menunggang seekor unta, dan kaki mereka luka sehingga dibalut dengan kain perca (riqa'). Dari situlah nama ekspedisi ini.\nDi sinilah buat pertama kalinya Baginda mengimamkan solat khauf, solat ketika takut diserang, dengan tentera dibahagikan dua kumpulan yang bergilir-gilir. Dalam perjalanan pulang, ketika Baginda berehat di bawah pokok, seorang lelaki musyrik mengambil pedang Baginda dan bertanya: “Siapa yang akan melindungimu daripadaku?” Baginda menjawab dengan tenang: “Allah.” Pedang itu jatuh dari tangannya, dan Baginda memaafkannya.",
   "The Prophet ﷺ marched into Najd to face tribes of Ghatafan who were gathering. The journey was very hard: six men took turns riding one camel, and their feet were so torn that they wrapped them in rags (riqa'). That is how the expedition got its name.\nHere for the first time he led the prayer of fear, prayed when an attack is feared, with the army split into two groups taking turns. On the way back, as he rested under a tree, an idolater took his sword and asked: “Who will protect you from me?” He calmly answered: “Allah.” The sword fell from the man's hand, and the Prophet forgave him."],
 l:[["Solat tidak ditinggalkan walaupun dalam ketakutan.","Prayer is not abandoned even in fear."],["Tawakal sepenuhnya kepada Allah dalam bahaya.","Complete trust in Allah in the face of danger."]],
 o:["Ramai ahli sejarah meletakkannya pada tahun 4 H. Ar-Raheeq memilih selepas Khaibar kerana Abu Musa dan Abu Hurairah turut serta.","Many historians place it in 4 AH. Ar-Raheeq places it after Khaibar because Abu Musa and Abu Hurayrah took part."],
 s:"The Expedition Called Dhat-ur-Riqa', p.240|"},

{id:"s98",n:98,e:10,m:1,y:629.2,ah:7,age:59,pl:"makkah",sc:"kaabah",
 w:["Zulkaedah 7 H (629)","Dhul-Qa'dah 7 AH (629)"],
 t:["Umrah al-Qadha'","The Compensatory 'Umrah"],
 f:["Setahun selepas Hudaibiyah, mengikut perjanjian, Rasulullah ﷺ berangkat dengan kira-kira dua ribu orang untuk menunaikan umrah. Quraisy mengosongkan Makkah dan memerhati dari bukit-bukit.\nKaum musyrikin menyangka orang Islam lemah kerana demam Madinah. Maka Baginda menyuruh mereka berlari-lari anak (ramal) pada tiga pusingan pertama tawaf dan mendedahkan bahu kanan, untuk menunjukkan kekuatan. Abdullah bin Rawahah memimpin unta Baginda sambil bersyair.\nMereka tinggal tiga hari seperti dalam perjanjian. Baginda berkahwin dengan Maimunah binti al-Harith. Sebahagian pemimpin Quraisy yang melihat umrah ini mula tertarik kepada Islam. Tidak lama kemudian, Khalid al-Walid, Amr bin al-'As dan Uthman bin Talhah memeluk Islam.",
   "A year after Hudaibiyah, as agreed, the Prophet ﷺ set out with about two thousand people to perform 'umrah. Quraysh left Makkah empty and watched from the hills.\nThe idolaters thought the Muslims were weak from the fever of Madinah. So he told them to jog (ramal) in the first three rounds of tawaf and to bare their right shoulders, to show their strength. 'Abdullah ibn Rawahah led his camel, reciting verse.\nThey stayed three days as the treaty allowed. He married Maymunah bint al-Harith. Some Quraysh leaders who saw this 'umrah were drawn to Islam. Soon after, Khalid ibn al-Walid, 'Amr ibn al-'As and 'Uthman ibn Talhah accepted Islam."],
 k:["Setahun selepas Hudaibiyah, Nabi ﷺ dan para sahabat dapat masuk ke Makkah dan menunaikan umrah dengan aman. Mereka bertawaf mengelilingi Kaabah dengan gembira.","A year after Hudaibiyah, the Prophet ﷺ and his companions entered Makkah and performed 'umrah in peace. They joyfully walked around the Kaabah."],
 l:[["Janji Allah dalam mimpi Rasul-Nya menjadi kenyataan.","Allah's promise in His Messenger's dream came true."],["Akhlak orang Islam ketika umrah menarik hati musuh.","The Muslims' conduct during 'umrah won over their enemies' hearts."]],
 ay:[{r:"al-Fath 48:27",ar:"لَّقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالْحَقِّ ۖ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَاءَ اللَّهُ آمِنِينَ",m:["Sesungguhnya Allah telah membenarkan mimpi Rasul-Nya dengan sebenarnya: kamu pasti akan memasuki Masjidil Haram, insya-Allah, dalam keadaan aman.","Allah has fulfilled His Messenger's vision in truth: you will surely enter the Sacred Masjid, if Allah wills, in safety."]}],
 p:["khalid"],s:"The Compensatory 'Umrah, p.243|Umrah al-Qada'"},

{id:"s99",n:99,e:10,m:1,y:629.7,ah:8,age:60,pl:"mutah",sc:"sunset",
 w:["Jamadilawal 8 H (Ogos atau September 629)","Jumada al-Ula 8 AH (August or September 629)"],
 t:["Perang Mu'tah","The Battle of Mu'tah"],
 f:["Utusan Rasulullah ﷺ, al-Harith bin Umair, dibunuh oleh seorang gabenor Ghassan, satu pelanggaran besar terhadap adat utusan. Baginda menghantar tiga ribu orang ke Syam dengan pesan: jika Zaid bin Harithah gugur, Ja'far bin Abi Talib mengambil alih, dan jika Ja'far gugur, Abdullah bin Rawahah.\nDi Mu'tah mereka berdepan dengan tentera Rom dan sekutu Arabnya, yang menurut Ar-Raheeq berjumlah kira-kira dua ratus ribu. Zaid gugur memegang panji. Ja'far mengambilnya, dan selepas kedua-dua tangannya terputus, beliau memeluk panji itu dengan lengannya hingga syahid. Abdullah bin Rawahah pula gugur.\nPara sahabat memilih Khalid al-Walid. Beliau menyusun semula barisan dengan bijak dan berjaya membawa tentera berundur dengan selamat. Hanya dua belas orang Islam syahid. Di Madinah, Rasulullah ﷺ mengkhabarkan berita itu dengan air mata, dan menggelar Khalid ‘salah satu pedang Allah’. Ja'far digelar at-Tayyar kerana diganti dua sayap di syurga.",
   "The Prophet's ﷺ envoy, al-Harith ibn 'Umayr, was killed by a Ghassanid governor, a grave violation of the custom protecting envoys. He sent three thousand men to Syria with the order: if Zayd ibn Harithah falls, Ja'far ibn Abi Talib takes command, and if Ja'far falls, 'Abdullah ibn Rawahah.\nAt Mu'tah they faced the Roman army and its Arab allies, which Ar-Raheeq numbers at about two hundred thousand. Zayd fell holding the banner. Ja'far took it, and after losing both hands he clasped it with his arms until he was martyred. Then 'Abdullah ibn Rawahah fell.\nThe companions chose Khalid ibn al-Walid. He skilfully reorganised the ranks and brought the army out safely. Only twelve Muslims were martyred. In Madinah the Prophet ﷺ gave the news with tears in his eyes, and called Khalid ‘one of the swords of Allah’. Ja'far was called at-Tayyar, as he was given two wings in Paradise in place of his hands."],
 k:["Tiga ribu orang Islam bertemu tentera yang sangat besar di Mu'tah. Tiga panglima yang berani gugur syahid. Kemudian Khalid al-Walid memimpin dan membawa tentera pulang dengan selamat.","Three thousand Muslims met a huge army at Mu'tah. Three brave commanders were martyred. Then Khalid ibn al-Walid took the lead and brought the army home safely."],
 l:[["Kepimpinan yang tersusun menyelamatkan tentera.","Planned leadership saves an army."],["Berundur dengan bijak juga satu kemenangan.","A wise withdrawal is also a victory."]],
 hd:[{r:"Sahih al-Bukhari 4262",m:["Anas (r.a.) meriwayatkan Baginda mengkhabarkan kematian Zaid, Ja'far dan Ibn Rawahah dengan mata yang berlinang, sehingga panji diambil oleh salah satu pedang Allah.","Anas (r.a.) narrated that he announced the deaths of Zayd, Ja'far and Ibn Rawahah with tearful eyes, until the banner was taken by one of the swords of Allah."]}],
 p:["zaid","jafar","khalid"],s:"The Battle of Mu'tah, p.245|Peperangan Mu'tah"},

{id:"s100",n:100,e:10,y:629.8,ah:8,age:60,pl:"najd",sc:"hoof",
 w:["Jamadilakhir & Syaaban 8 H","Jumada al-Akhirah and Sha'ban 8 AH"],
 t:["Dzat as-Salasil & Khadirah","Dhat as-Salasil and Khadirah"],
 f:["Selepas Mu'tah, beberapa kabilah Arab di sempadan Syam berhimpun untuk menyerang Madinah. Rasulullah ﷺ menghantar Amr bin al-'As dengan tiga ratus orang ke Dzat as-Salasil. Apabila melihat musuh ramai, Amr meminta bantuan, lalu Baginda menghantar dua ratus orang di bawah Abu Ubaidah, termasuk Abu Bakar dan Umar. Musuh bertempiaran lari.\nPada bulan Syaaban, Abu Qatadah dihantar dengan lima belas orang ke Khadirah di Najd untuk menghadapi kabilah Ghatafan, dan pulang dengan selamat.",
   "After Mu'tah, some Arab tribes on the Syrian border gathered to attack Madinah. The Prophet ﷺ sent 'Amr ibn al-'As with three hundred men to Dhat as-Salasil. Seeing how many the enemy were, 'Amr asked for help, so he sent two hundred more under Abu 'Ubaydah, including Abu Bakr and 'Umar. The enemy scattered.\nIn Sha'ban, Abu Qatadah was sent with fifteen men to Khadirah in Najd to face Ghatafan, and returned safely."],
 l:[["Taat kepada ketua walaupun ketua itu baru memeluk Islam.","Obey the commander even if he is new to Islam."]],
 s:"Dhat As-Salasil Campaign; Khadrah Campaign, p.245|Peperangan Zat al-Salasil; Pengutusan Abu Qutadah ke Khudrah"},

{id:"s101",n:101,e:10,m:1,y:630.0,ah:8,age:60,pl:"makkah",sc:"fath",
 w:["Ramadan 8 H (Januari 630)","Ramadan 8 AH (January 630)"],
 t:["Pembukaan Kota Makkah","The Conquest of Makkah"],
 f:["Bani Bakr, sekutu Quraisy, menyerang Bani Khuza'ah, sekutu orang Islam, dengan bantuan senjata dan orang Quraisy. Perjanjian Hudaibiyah pun terbatal. Abu Sufyan datang ke Madinah untuk memperbaharuinya, tetapi gagal.\nPada 10 Ramadan 8 H, Rasulullah ﷺ berangkat secara rahsia dengan sepuluh ribu orang. Di Marr az-Zahran, ribuan unggun api dinyalakan. Abu Sufyan keluar meninjau, dibawa kepada Baginda oleh al-'Abbas, lalu memeluk Islam. Baginda mengumumkan: sesiapa yang masuk ke rumah Abu Sufyan selamat, sesiapa yang menutup pintu rumahnya selamat, dan sesiapa yang masuk ke Masjidil Haram selamat.\nTentera Islam masuk dari empat arah hampir tanpa pertempuran. Baginda menundukkan kepala di atas untanya kerana rendah diri. Baginda menjatuhkan 360 berhala di sekeliling Kaabah sambil membaca: “Kebenaran telah datang dan kebatilan telah lenyap.” Bilal melaungkan azan dari atas Kaabah. Baginda berdiri di hadapan Quraisy yang pernah mengusir dan memeranginya, lalu berkata: “Tiada celaan ke atas kamu hari ini. Pergilah, kamu semua bebas.”",
   "Banu Bakr, allies of Quraysh, attacked Banu Khuza'ah, allies of the Muslims, with Quraysh weapons and men. The Treaty of Hudaibiyah was broken. Abu Sufyan came to Madinah to renew it, but failed.\nOn 10 Ramadan 8 AH the Prophet ﷺ set out in secret with ten thousand men. At Marr az-Zahran thousands of campfires were lit. Abu Sufyan came out to look, was brought to him by al-'Abbas, and accepted Islam. The Prophet announced: whoever enters Abu Sufyan's house is safe, whoever shuts his door is safe, and whoever enters the Sacred Masjid is safe.\nThe Muslim army entered from four sides with almost no fighting. He bowed his head low on his camel in humility. He brought down the 360 idols around the Kaabah, reciting: “Truth has come and falsehood has vanished.” Bilal called the azan from the roof of the Kaabah. He stood before the Quraysh who had driven him out and fought him, and said: “No blame on you today. Go, you are all free.”"],
 k:["Nabi ﷺ kembali ke Makkah dengan sepuluh ribu orang. Hampir tiada pertempuran. Baginda memaafkan semua orang yang pernah menyakitinya dan berkata: “Pergilah, kamu semua bebas.” Bilal melaungkan azan di atas Kaabah.","The Prophet ﷺ returned to Makkah with ten thousand people. There was almost no fighting. He forgave everyone who had hurt him and said: “Go, you are all free.” Bilal called the azan from the top of the Kaabah."],
 l:[["Kemaafan ketika berkuasa ialah kemuncak akhlak.","Forgiveness in the hour of power is the peak of character."],["Rendah diri ketika menang.","Humility in victory."],["Tauhid dikembalikan ke Rumah Allah.","The oneness of Allah was restored to His House."]],
 ay:[{kid:1,r:"al-Isra' 17:81",ar:"وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ ۚ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا",m:["Dan katakanlah: Kebenaran telah datang dan kebatilan telah lenyap. Sesungguhnya kebatilan itu pasti lenyap.","And say: Truth has come and falsehood has vanished. Indeed falsehood is bound to vanish."]}],
 hd:[{r:"Sahih al-Bukhari 4287",m:["Ibn Mas'ud (r.a.) menceritakan Baginda menjatuhkan berhala di sekeliling Kaabah sambil membaca ayat ini.","Ibn Mas'ud (r.a.) related that he struck down the idols around the Kaabah while reciting this verse."]}],
 o:["Ar-Raheeq menyebut Baginda meninggalkan Marr az-Zahran pada pagi Selasa, 17 Ramadan 8 H.","Ar-Raheeq says he left Marr az-Zahran on the morning of Tuesday, 17 Ramadan 8 AH."],
 p:["abusufyan","bilal","khalid"],s:"The Conquest of Makkah, p.249|Peperangan pembukaan Kota Mekah"},

{id:"s102",n:102,e:11,m:1,y:630.1,ah:8,age:60,pl:"hunain",sc:"hunain",
 w:["Syawal 8 H (630)","Shawwal 8 AH (630)"],
 t:["Perang Hunain","The Battle of Hunain"],
 f:["Kabilah Hawazin dan Thaqif, di bawah Malik bin Auf, berhimpun untuk menyerang dengan membawa wanita, anak dan ternakan mereka supaya tiada siapa lari. Rasulullah ﷺ keluar dengan dua belas ribu orang, tentera Islam terbesar ketika itu. Ada yang berkata: “Kita tidak akan kalah hari ini kerana ramai.”\nPada waktu subuh, ketika memasuki lembah Hunain, mereka diserang hendap dengan anak panah dari celah-celah bukit. Ramai yang bertempiaran lari. Rasulullah ﷺ tetap teguh di atas baghalnya sambil berseru: “Akulah Nabi, bukan dusta. Akulah anak Abdul Muttalib.” Al-'Abbas, yang bersuara lantang, memanggil para sahabat, dan mereka kembali menyahut.\nPertempuran berbalik. Hawazin kalah, dan harta rampasan yang sangat banyak dikumpulkan: enam ribu tawanan, dua puluh empat ribu unta dan lebih empat puluh ribu kambing.",
   "The tribes of Hawazin and Thaqif under Malik ibn 'Awf gathered to attack, bringing their women, children and herds so that no one would flee. The Prophet ﷺ marched out with twelve thousand men, the largest Muslim army so far. Some said: “We will not be beaten today for lack of numbers.”\nAt dawn, as they entered the valley of Hunain, they were ambushed with arrows from the hillsides. Many fled. The Prophet ﷺ stood firm on his mule, calling: “I am the Prophet, no lie. I am the son of 'Abdul-Muttalib.” Al-'Abbas, who had a loud voice, called the companions, and they came back answering.\nThe battle turned. Hawazin were defeated, and vast spoils were gathered: six thousand captives, twenty-four thousand camels and more than forty thousand sheep."],
 k:["Di Hunain, orang Islam sangat ramai dan ada yang terlalu yakin. Mereka diserang secara tiba-tiba dan ramai lari. Tetapi Nabi ﷺ tetap berani dan memanggil mereka kembali. Dengan pertolongan Allah, mereka menang.","At Hunain, the Muslims were very many and some felt too sure of themselves. They were attacked by surprise and many ran. But the Prophet ﷺ stayed brave and called them back. With Allah's help, they won."],
 l:[["Jangan bangga dengan jumlah yang ramai.","Do not be proud of great numbers."],["Keteguhan pemimpin mengembalikan semangat pengikut.","A leader's steadfastness restores his followers' courage."]],
 ay:[{r:"at-Taubah 9:25",ar:"لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَةٍ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ",m:["Sesungguhnya Allah telah menolong kamu di banyak medan, dan pada hari Hunain ketika kamu berbangga dengan jumlah kamu yang ramai.","Allah has given you victory in many places, and on the day of Hunain, when your great numbers pleased you."]}],
 hd:[{r:"Sahih al-Bukhari 2864",m:["Al-Bara' (r.a.) meriwayatkan Baginda berseru di Hunain: “Akulah Nabi, bukan dusta. Akulah anak Abdul Muttalib.”","Al-Bara' (r.a.) narrated that at Hunain he called out: “I am the Prophet, no lie. I am the son of 'Abdul-Muttalib.”"]}],
 s:"Hunain Ghazwah, p.258|Peperangan Hunain"},

{id:"s103",n:103,e:11,y:630.15,ah:8,age:60,pl:"taif",sc:"taif",
 w:["Syawal 8 H","Shawwal 8 AH"],
 t:["Kepungan Ta'if","The siege of Ta'if"],
 f:["Sisa tentera Thaqif berlindung di dalam kota Ta'if yang berkubu kuat. Rasulullah ﷺ mengepung kota itu dan buat pertama kalinya menggunakan manjanik (pelontar batu). Penduduknya bertahan dengan anak panah dan besi panas, dan beberapa orang Islam syahid.\nSelepas beberapa minggu, Baginda bermesyuarat dan memutuskan untuk menamatkan kepungan. Para sahabat meminta Baginda mendoakan keburukan untuk Thaqif. Sebaliknya Baginda berdoa: “Ya Allah, berilah hidayah kepada Thaqif dan bawalah mereka (kepada Islam).” Setahun kemudian, Thaqif datang sendiri ke Madinah dan memeluk Islam.\nKota yang pernah melontar Baginda dengan batu sepuluh tahun sebelumnya akhirnya menerima Islam.",
   "The remnants of Thaqif took refuge inside the strongly fortified town of Ta'if. The Prophet ﷺ besieged it and, for the first time, used a catapult. The defenders held out with arrows and hot iron, and some Muslims were martyred.\nAfter some weeks he consulted and decided to lift the siege. The companions asked him to pray against Thaqif. Instead he prayed: “O Allah, guide Thaqif and bring them (to Islam).” A year later Thaqif came to Madinah of their own accord and accepted Islam.\nThe town that had stoned him ten years earlier finally embraced Islam."],
 l:[["Doa untuk hidayah lebih baik daripada doa untuk kebinasaan.","Praying for guidance is better than praying for ruin."]],
 o:["Riwayat berbeza tentang tempoh kepungan ini, antara sepuluh hingga empat puluh hari.","Reports differ on how long the siege lasted, from ten to forty days."],
 s:"Ta'if Campaign, p.258|"},

{id:"s104",n:104,e:11,y:630.2,ah:8,age:60,pl:"jiranah",sc:"tents",
 w:["Zulkaedah 8 H","Dhul-Qa'dah 8 AH"],
 t:["Al-Ji'ranah: harta rampasan & tangisan Ansar","Al-Ji'ranah: the spoils and the Ansar's tears"],
 f:["Di al-Ji'ranah, Rasulullah ﷺ menunggu lebih sepuluh malam, berharap Hawazin datang bertaubat, sebelum membahagikan harta rampasan. Baginda memberi bahagian besar kepada pemimpin Quraisy dan Arab yang baru memeluk Islam untuk melembutkan hati mereka. Ansar tidak mendapat bahagian sebegitu, dan sebahagian mereka berasa terkilan.\nBaginda mengumpulkan Ansar dan berucap: “Tidakkah kamu dahulu sesat lalu Allah memberi kamu hidayah melaluiku? Tidakkah kamu reda orang lain pulang membawa kambing dan unta, sedangkan kamu pulang membawa Rasulullah ke rumah kamu? Jika manusia melalui satu lembah dan Ansar melalui lembah lain, aku akan melalui lembah Ansar.” Mereka menangis hingga basah janggut dan berkata: “Kami reda dengan Rasulullah sebagai bahagian kami.”\nKemudian rombongan Hawazin datang memeluk Islam, dan tawanan mereka dipulangkan. Baginda menunaikan umrah dari al-Ji'ranah lalu pulang ke Madinah.",
   "At al-Ji'ranah the Prophet ﷺ waited more than ten nights, hoping Hawazin would come in repentance, before dividing the spoils. He gave large shares to Quraysh and Arab leaders newly in Islam, to win their hearts. The Ansar received no such shares, and some of them felt hurt.\nHe gathered the Ansar and said: “Were you not astray, and Allah guided you through me? Are you not content that people go home with sheep and camels, while you go home with the Messenger of Allah? If people went down one valley and the Ansar another, I would take the valley of the Ansar.” They wept until their beards were wet and said: “We are content with the Messenger of Allah as our share.”\nThen a Hawazin delegation came and accepted Islam, and their captives were returned. He performed 'umrah from al-Ji'ranah and went back to Madinah."],
 l:[["Menjelaskan secara terbuka menghilangkan salah faham.","Speaking openly clears misunderstanding."],["Cinta kepada Rasul lebih berharga daripada harta.","Love for the Messenger is worth more than wealth."]],
 hd:[{r:"Sahih al-Bukhari 4330",m:["Abdullah bin Zaid (r.a.) meriwayatkan ucapan Baginda kepada Ansar di Hunain.","'Abdullah ibn Zayd (r.a.) narrated his address to the Ansar after Hunain."]}],
 s:"The Distribution of the Booty at al-Ji'ranah, p.258|"},

{id:"s105",n:105,e:11,m:1,y:630.8,ah:9,age:61,pl:"tabuk",sc:"tabuk",
 w:["Rejab 9 H (Oktober 630)","Rajab 9 AH (October 630)"],
 t:["Perang Tabuk & tiga sahabat yang tertinggal","Tabuk and the three who stayed behind"],
 f:["Berita sampai bahawa Rom dan sekutunya Ghassan sedang bersiap untuk menyerang. Ketika itu musim panas yang terik, musim buah kurma, dan masa sukar. Rasulullah ﷺ menyeru persiapan secara terbuka. Abu Bakar menyumbang semua hartanya, Umar separuh, dan Uthman melengkapkan sebahagian besar tentera. Tentera ini digelar Jaisy al-'Usrah, tentera masa sukar. Seramai tiga puluh ribu orang keluar.\nMereka tinggal dua puluh hari di Tabuk, tetapi Rom tidak muncul. Baginda membuat perjanjian dengan pemerintah Ailah, Jarba' dan Adhruh. Golongan munafik tinggal di belakang dengan pelbagai alasan.\nTiga sahabat yang ikhlas, Ka'b bin Malik, Murarah bin ar-Rabi' dan Hilal bin Umayyah, juga tertinggal tanpa alasan. Mereka berkata benar dan tidak berdalih. Orang Islam diperintah memulaukan mereka selama lima puluh hari, sehingga bumi terasa sempit. Kemudian Allah menurunkan ayat menerima taubat mereka.",
   "News came that Rome and its Ghassanid allies were preparing to attack. It was a scorching summer, date-harvest time, and a hard season. The Prophet ﷺ called openly for preparation. Abu Bakr gave all his wealth, 'Umar half, and 'Uthman equipped a large part of the army. It was called Jaysh al-'Usrah, the army of hardship. Thirty thousand set out.\nThey stayed twenty days at Tabuk, but the Romans never appeared. He made treaties with the rulers of Aylah, Jarba' and Adhruh. The hypocrites stayed behind with all kinds of excuses.\nThree sincere companions, Ka'b ibn Malik, Murarah ibn ar-Rabi' and Hilal ibn Umayyah, also stayed behind with no excuse. They told the truth and made no pretence. The Muslims were ordered to shun them for fifty days, until the earth felt narrow for them. Then Allah revealed verses accepting their repentance."],
 k:["Nabi ﷺ mengetuai tiga puluh ribu orang ke Tabuk pada musim yang sangat panas. Ramai sahabat memberikan harta mereka. Tiga orang sahabat tertinggal, tetapi mereka berkata benar, dan Allah menerima taubat mereka.","The Prophet ﷺ led thirty thousand people to Tabuk in a very hot season. Many companions gave their wealth. Three companions stayed behind, but they told the truth, and Allah accepted their repentance."],
 l:[["Berkata benar walaupun pahit membawa keselamatan.","Telling the truth, even when bitter, brings salvation."],["Berlumba-lumba dalam kebaikan.","Compete with each other in doing good."]],
 ay:[{r:"at-Taubah 9:118",ar:"وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا",m:["Dan (Allah menerima taubat) tiga orang yang ditangguhkan (keputusan taubat mereka).","And (Allah turned in mercy) to the three who were left behind."]}],
 hd:[{r:"Sahih al-Bukhari 4418",m:["Ka'b bin Malik (r.a.) menceritakan sendiri kisahnya tertinggal dari Tabuk.","Ka'b ibn Malik (r.a.) told his own story of staying behind from Tabuk."]}],
 p:["kab","abubakar","umar","uthman"],s:"The Invasion of Tabuk, p.272|Ghazwah Tabuk"},

{id:"s106",n:106,e:11,y:631.2,ah:9,age:61,pl:"makkah",sc:"kaabah",
 w:["Zulkaedah atau Zulhijjah 9 H","Dhul-Qa'dah or Dhul-Hijjah 9 AH"],
 t:["Abu Bakar mengetuai haji: Surah Bara'ah","Abu Bakr leads the Hajj: Surah Bara'ah"],
 f:["Pada tahun kesembilan Hijrah, Rasulullah ﷺ melantik Abu Bakar mengetuai jemaah haji. Selepas itu turun permulaan Surah Bara'ah (at-Taubah). Baginda menghantar Ali untuk mengumumkannya kepada orang ramai pada hari korban.\nAntara pengumumannya: selepas tahun itu, orang musyrik tidak boleh lagi menunaikan haji, dan tiada siapa boleh tawaf dalam keadaan telanjang seperti adat jahiliah. Perjanjian dengan musyrikin yang setia dihormati hingga tamat tempohnya. Haji ini menjadi persiapan kepada haji Rasulullah ﷺ pada tahun berikutnya.",
   "In the ninth year after the Hijrah, the Prophet ﷺ appointed Abu Bakr to lead the pilgrims. Afterwards the opening of Surah Bara'ah (at-Tawbah) was revealed. He sent 'Ali to announce it to the people on the day of sacrifice.\nAmong the announcements: after that year no idolater could perform Hajj, and no one could circle the Kaabah naked as in the days of ignorance. Treaties with idolaters who had kept faith would be honoured to the end of their term. This Hajj prepared the way for the Prophet's ﷺ own Hajj the following year."],
 l:[["Ibadah haji dibersihkan daripada amalan jahiliah.","The Hajj was cleansed of the practices of ignorance."]],
 ay:[{r:"at-Taubah 9:1",ar:"بَرَاءَةٌ مِّنَ اللَّهِ وَرَسُولِهِ",m:["(Inilah) pemutusan hubungan daripada Allah dan Rasul-Nya.","A declaration of disassociation from Allah and His Messenger."]}],
 p:["abubakar","ali"],s:"Abu Bakr Performs the Pilgrimage, p.281|"},

{id:"s107",n:107,e:11,m:1,y:631.3,ah:9,age:"61–62",pl:"madinah",sc:"caravan",
 w:["9 H hingga 10 H","9 AH to 10 AH"],
 t:["Tahun Perutusan","The Year of Delegations"],
 f:["Selepas pembukaan Makkah dan Tabuk, kabilah-kabilah Arab yang selama ini menunggu melihat siapa yang menang mula datang ke Madinah. Ar-Raheeq menyebut lebih tujuh puluh rombongan, kebanyakannya pada tahun 9 dan 10 H. Antaranya Thaqif dari Ta'if, Bani Tamim, Bani Hanifah, Hamdan, Tayy bersama Adi bin Hatim, Abdul Qais, dan Nasrani Najran.\nRasulullah ﷺ menyambut mereka dengan mesra di masjid, mengajar mereka Islam, dan menghantar guru serta pemungut zakat bersama mereka pulang. Inilah masa yang disebut dalam Surah an-Nasr: manusia memasuki agama Allah dengan berbondong-bondong.",
   "After the conquest of Makkah and Tabuk, the Arab tribes who had been waiting to see who would prevail began coming to Madinah. Ar-Raheeq mentions more than seventy delegations, most in 9 and 10 AH. Among them were Thaqif of Ta'if, Banu Tamim, Banu Hanifah, Hamdan, Tayy with 'Adi ibn Hatim, 'Abd al-Qays, and the Christians of Najran.\nThe Prophet ﷺ received them warmly in the masjid, taught them Islam, and sent teachers and zakat collectors home with them. This is the time described in Surah an-Nasr: people entering the religion of Allah in crowds."],
 k:["Banyak rombongan dari seluruh tanah Arab datang ke Madinah untuk bertemu Nabi ﷺ dan memeluk Islam. Tahun ini dipanggil Tahun Perutusan.","Many groups from all over Arabia came to Madinah to meet the Prophet ﷺ and accept Islam. This year is called the Year of Delegations."],
 l:[["Kesabaran bertahun-tahun membuahkan hasil.","Years of patience bear fruit."],["Tetamu disambut dengan mesra dan diajar dengan lembut.","Guests are welcomed warmly and taught gently."]],
 ay:[{kid:1,r:"an-Nasr 110:1-2",ar:"إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ۝ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا",m:["Apabila datang pertolongan Allah dan kemenangan, dan engkau melihat manusia memasuki agama Allah dengan berbondong-bondong.","When the help of Allah and the victory come, and you see people entering the religion of Allah in crowds."]}],
 s:"People Embrace the Religion of Allah in Large Crowds, p.285; The Delegations, p.286|"},

{id:"s108",n:108,e:11,m:1,y:632.2,ah:10,age:62,pl:"arafah",sc:"arafah",
 w:["Zulhijjah 10 H (Mac 632)","Dhul-Hijjah 10 AH (March 632)"],
 t:["Haji Wada' & khutbah Arafah","The Farewell Hajj and the sermon at Arafah"],
 f:["Pada tahun kesepuluh Hijrah, Rasulullah ﷺ mengumumkan niat untuk menunaikan haji. Orang ramai datang dari seluruh semenanjung. Baginda bertolak dari Madinah pada hari Sabtu, 25 Zulkaedah. Di Arafah, menurut Ar-Raheeq, seratus dua puluh empat atau seratus empat puluh empat ribu orang berhimpun.\nDi atas untanya, Baginda menyampaikan khutbah: darah, harta dan maruah kamu adalah suci seperti sucinya hari, bulan dan tanah ini; riba jahiliah dihapuskan; berbuat baiklah kepada wanita; dan aku tinggalkan kepada kamu Kitab Allah, yang jika kamu berpegang kepadanya kamu tidak akan sesat. Baginda bertanya: “Adakah aku telah menyampaikan?” Mereka menjawab: “Ya.” Baginda menunjuk ke langit: “Ya Allah, saksikanlah.”\nPada hari itu turun ayat: “Pada hari ini telah Aku sempurnakan agamamu.” Ramai yang merasakan ia tanda perpisahan.",
   "In the tenth year after the Hijrah, the Prophet ﷺ announced that he would perform Hajj. People came from all over the peninsula. He left Madinah on Saturday, 25 Dhul-Qa'dah. At Arafah, according to Ar-Raheeq, a hundred and twenty-four or a hundred and forty-four thousand people gathered.\nFrom his camel he delivered his sermon: your blood, your property and your honour are sacred, as sacred as this day, this month and this land; the usury of the age of ignorance is abolished; treat women well; and I leave you the Book of Allah, which if you hold to it you will never go astray. He asked: “Have I conveyed the message?” They said: “Yes.” He pointed to the sky: “O Allah, bear witness.”\nThat day the verse came down: “This day I have perfected your religion for you.” Many sensed it was a farewell."],
 k:["Nabi ﷺ menunaikan haji bersama lebih seratus ribu orang. Di Padang Arafah, Baginda berpesan supaya semua orang berbuat baik, adil, dan berpegang kepada al-Quran. Ini haji terakhir Baginda.","The Prophet ﷺ performed Hajj with more than a hundred thousand people. At the plain of Arafah he told everyone to be kind, be fair, and hold on to the Quran. It was his last Hajj."],
 l:[["Hak asasi manusia diumumkan dengan jelas di Arafah.","Human rights were proclaimed clearly at Arafah."],["Al-Quran dan sunnah ialah pegangan selepas Rasul.","The Quran and sunnah are what to hold to after the Messenger."]],
 ay:[{r:"al-Ma'idah 5:3",ar:"الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا",m:["Pada hari ini telah Aku sempurnakan agamamu untukmu, dan telah Aku cukupkan nikmat-Ku kepadamu, dan telah Aku reda Islam sebagai agamamu.","This day I have perfected your religion for you, completed My favour upon you, and approved Islam as your religion."]}],
 hd:[{r:"Sahih Muslim 1218",m:["Jabir bin Abdullah (r.a.) meriwayatkan perjalanan haji Baginda dan khutbah di Arafah dengan terperinci.","Jabir ibn 'Abdullah (r.a.) narrated his Hajj and the sermon at Arafah in detail."]}],
 s:"The Farewell Pilgrimage, p.298|Hajjah al-Wida'"},

{id:"s109",n:109,e:11,y:632.35,ah:11,age:62,pl:"madinah",sc:"hoof",
 w:["Safar 11 H","Safar 11 AH"],
 t:["Pasukan Usamah","Usamah's army"],
 f:["Pada bulan Safar 11 H, Rasulullah ﷺ menyediakan sebuah pasukan untuk ke wilayah Balqa' di Syam, tempat ayah Usamah, Zaid bin Harithah, gugur di Mu'tah. Baginda melantik Usamah bin Zaid, yang ketika itu masih sangat muda, sebagai panglima, walaupun pasukan itu termasuk sahabat-sahabat besar.\nAda yang mempertikaikan perlantikan itu. Baginda bersabda: “Jika kamu mempertikaikan kepimpinannya, kamu juga pernah mempertikaikan kepimpinan ayahnya. Demi Allah, dia layak memimpin.” Pasukan itu berkhemah di luar Madinah, tetapi tertangguh kerana Baginda jatuh sakit. Ia akhirnya diberangkatkan oleh Abu Bakar selepas Baginda wafat.",
   "In Safar 11 AH the Prophet ﷺ prepared an army for the Balqa' region of Syria, where Usamah's father, Zayd ibn Harithah, had fallen at Mu'tah. He appointed Usamah ibn Zayd, then very young, as its commander, though the army included senior companions.\nSome questioned the appointment. He said: “If you question his leadership, you questioned his father's before him. By Allah, he is worthy to lead.” The army camped outside Madinah but was delayed by the Prophet's illness. Abu Bakr finally sent it out after his passing."],
 l:[["Kelayakan diukur dengan kemampuan, bukan usia.","Ability, not age, is the measure of fitness to lead."]],
 hd:[{r:"Sahih al-Bukhari 4469",m:["Ibn Umar (r.a.) meriwayatkan sabda Baginda tentang kelayakan Usamah dan ayahnya untuk memimpin.","Ibn 'Umar (r.a.) narrated his words on the fitness of Usamah and his father to lead."]}],
 p:["usamah","zaid","abubakar"],s:"The Last Expeditions, p.303|"},

{id:"s110",n:110,e:11,y:632.4,ah:11,age:62,pl:"madinah",sc:"madinah",
 w:["Akhir Safar 11 H","Late Safar 11 AH"],
 t:["Tanda-tanda perpisahan & permulaan sakit","Signs of farewell; the illness begins"],
 f:["Tanda-tanda perpisahan sudah kelihatan. Pada Ramadan 10 H, Rasulullah ﷺ beriktikaf dua puluh hari, bukan sepuluh seperti biasa, dan Jibril mengulang al-Quran bersamanya dua kali. Di Haji Wada' Baginda berkata: “Mungkin aku tidak akan bertemu kamu lagi selepas tahun ini.” Baginda menziarahi syuhada Uhud seolah-olah mengucapkan selamat tinggal, dan berdoa untuk ahli kubur Baqi' pada waktu malam.\nPada akhir Safar, sekembalinya dari pengebumian di Baqi', Baginda mula sakit kepala dan demam yang tinggi. Baginda tetap mengimamkan solat walaupun sakit. Apabila sakitnya bertambah, Baginda meminta izin isteri-isterinya untuk dirawat di rumah Aisyah.",
   "The signs of farewell were already there. In Ramadan 10 AH the Prophet ﷺ spent twenty days in i'tikaf instead of the usual ten, and Jibril went over the Quran with him twice. At the Farewell Hajj he said: “Perhaps I will not meet you again after this year.” He visited the martyrs of Uhud as if bidding them farewell, and prayed for those buried at al-Baqi' by night.\nAt the end of Safar, returning from a funeral at al-Baqi', he was struck by a headache and high fever. He kept leading the prayers despite the illness. When it grew worse, he asked his wives' permission to be nursed in 'A'ishah's house."],
 l:[["Bersedia untuk bertemu Allah dengan memperbanyak ibadah.","Prepare to meet Allah by increasing worship."]],
 s:"The Journey to Allah: Symptoms of Farewell; The Start of the Disease, p.304|Menemui Allah"},

{id:"s111",n:111,e:11,y:632.42,ah:11,age:63,pl:"madinah",sc:"masjid",
 w:["Rabiulawal 11 H","Rabi' al-Awwal 11 AH"],
 t:["Minggu terakhir: Abu Bakar mengimamkan solat","The last week: Abu Bakr leads the prayer"],
 f:["Lima hari sebelum wafat, Rasulullah ﷺ duduk di atas mimbar dengan kepala berbalut dan bersabda: “Seorang hamba diberi pilihan antara dunia dan apa yang ada di sisi Allah, lalu dia memilih apa yang ada di sisi Allah.” Abu Bakar menangis, kerana memahami bahawa hamba itu ialah Baginda sendiri. Baginda memuji Abu Bakar dan memerintahkan semua pintu ke masjid ditutup kecuali pintu Abu Bakar.\nApabila Baginda tidak lagi mampu keluar, Baginda memerintahkan: “Suruhlah Abu Bakar mengimamkan orang ramai.” Abu Bakar mengimamkan tujuh belas waktu solat semasa hayat Baginda. Baginda berpesan tentang solat dan tentang hamba sahaya, dan memerdekakan hamba-hambanya serta menyedekahkan wang yang masih ada.",
   "Five days before his death, the Prophet ﷺ sat on the pulpit with his head bandaged and said: “A servant was given the choice between this world and what is with Allah, and he chose what is with Allah.” Abu Bakr wept, understanding that the servant was the Prophet himself. He praised Abu Bakr and ordered every door into the masjid closed except Abu Bakr's.\nWhen he could no longer go out, he ordered: “Tell Abu Bakr to lead the people in prayer.” Abu Bakr led seventeen prayers in his lifetime. He urged them to guard the prayer and to treat their servants well, freed his slaves and gave away the money he still had."],
 l:[["Solat ialah wasiat terakhir Rasulullah ﷺ.","Prayer was the Prophet's ﷺ last instruction."]],
 hd:[{r:"Sahih al-Bukhari 466",m:["Abu Sa'id al-Khudri (r.a.) meriwayatkan khutbah tentang hamba yang diberi pilihan, dan tangisan Abu Bakar.","Abu Sa'id al-Khudri (r.a.) narrated the sermon about the servant given a choice, and Abu Bakr's tears."]},{r:"Sahih al-Bukhari 664",m:["Aisyah (r.a.) meriwayatkan perintah Baginda: “Suruhlah Abu Bakar mengimamkan orang ramai.”","'A'ishah (r.a.) narrated his order: “Tell Abu Bakr to lead the people in prayer.”"]}],
 p:["abubakar","aisyah"],s:"The Last Week, p.304|Minggu terakhir"},

{id:"s112",n:112,e:11,m:1,y:632.44,ah:11,age:63,pl:"madinah",sc:"sunset",
 w:["Isnin, 12 Rabiulawal 11 H (Jun 632), waktu dhuha","Monday, 12 Rabi' al-Awwal 11 AH (June 632), in the forenoon"],
 t:["Wafat Rasulullah ﷺ","The passing of the Prophet ﷺ"],
 f:["Pada pagi Isnin, ketika orang Islam bersolat subuh di belakang Abu Bakar, Rasulullah ﷺ menyelak tirai bilik Aisyah dan tersenyum melihat mereka bersaf. Mereka menyangka Baginda sudah sembuh.\nMenjelang dhuha, Baginda memanggil Fatimah dan berbisik kepadanya. Fatimah menangis, kemudian tersenyum, kerana diberitahu bahawa dialah ahli keluarga pertama yang akan menyusul ayahandanya. Baginda bersandar di dada Aisyah, bersugi dengan kayu sugi yang dilembutkan oleh Aisyah, dan mencelup tangannya ke dalam bekas air sambil menyapu wajahnya dan berkata: “La ilaha illallah. Sesungguhnya kematian itu ada sakaratnya.”\nBaginda mengangkat jarinya ke atas, matanya memandang ke langit, dan bibirnya berbisik: “Bersama orang-orang yang Engkau beri nikmat... Ya Allah, ampunilah aku, kasihanilah aku, dan pertemukan aku dengan ar-Rafiq al-A'la. Ya Allah, ar-Rafiq al-A'la.” Lalu tangannya jatuh perlahan. Baginda wafat pada usia 63 tahun dan 4 hari.",
   "On Monday morning, as the Muslims prayed fajr behind Abu Bakr, the Prophet ﷺ lifted the curtain of 'A'ishah's room and smiled to see them in their rows. They thought he had recovered.\nNear mid-morning he called Fatimah and whispered to her. She wept, then smiled, because he told her she would be the first of his family to follow him. He rested against 'A'ishah's chest, cleaned his teeth with a siwak she had softened, and dipped his hand into a bowl of water, wiping his face and saying: “La ilaha illallah. Death has its agonies.”\nHe raised his finger, his eyes turned upward, and his lips whispered: “With those You have blessed... O Allah, forgive me, have mercy on me, and join me to the Highest Companion. O Allah, the Highest Companion.” Then his hand slowly fell. He passed away aged 63 years and 4 days."],
 k:["Pada usia 63 tahun, Nabi Muhammad ﷺ jatuh sakit dan kembali ke rahmatullah di Madinah. Semua orang sangat sedih. Tetapi ajaran Baginda, al-Quran dan sunnah, kekal bersama kita hingga hari ini.","At 63 years old, Prophet Muhammad ﷺ fell ill and returned to Allah in Madinah. Everyone was very sad. But his teachings, the Quran and the sunnah, stay with us to this day."],
 l:[["Kalimah terakhir Baginda ialah tauhid dan doa untuk bertemu Allah.","His last words were of the oneness of Allah and longing to meet Him."],["Setiap jiwa akan merasai mati, termasuk manusia termulia.","Every soul will taste death, even the noblest of people."]],
 ay:[{r:"az-Zumar 39:30",ar:"إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ",m:["Sesungguhnya engkau akan mati dan sesungguhnya mereka juga akan mati.","Indeed you will die, and indeed they will die."]}],
 hd:[{r:"Sahih al-Bukhari 4463",m:["Aisyah (r.a.) mendengar Baginda menyebut: “Ya Allah, ar-Rafiq al-A'la,” sebelum wafat.","'A'ishah (r.a.) heard him say: “O Allah, the Highest Companion,” before he passed."]}],
 p:["aisyah","fatimah","abubakar"],s:"The Prophet Breathes His Last, p.304|Hari terakhir dalam hayat Baginda"},

{id:"s113",n:113,e:11,y:632.441,ah:11,pl:"madinah",sc:"masjid",
 w:["Isnin, 12 Rabiulawal 11 H","Monday, 12 Rabi' al-Awwal 11 AH"],
 t:["Sikap Umar & ucapan Abu Bakar","'Umar's shock and Abu Bakr's speech"],
 f:["Berita wafat itu menggoncang Madinah. Umar bin al-Khattab tidak dapat menerimanya. Beliau berdiri dan berkata bahawa Rasulullah ﷺ tidak wafat, tetapi pergi menemui Tuhannya seperti Nabi Musa, dan akan kembali.\nAbu Bakar datang dari rumahnya di as-Sunh, masuk menemui jasad Baginda, membuka kain penutup wajahnya dan menciumnya sambil menangis: “Alangkah indahnya engkau ketika hidup dan ketika wafat.” Kemudian beliau keluar dan berucap kepada orang ramai: “Sesiapa yang menyembah Muhammad, maka Muhammad telah wafat. Sesiapa yang menyembah Allah, maka Allah Maha Hidup dan tidak akan mati.” Beliau membaca ayat Ali 'Imran 3:144.\nOrang ramai seolah-olah belum pernah mendengar ayat itu. Umar berkata kakinya terasa lemah dan beliau jatuh ke tanah, kerana baru sedar bahawa Rasulullah ﷺ benar-benar telah wafat.",
   "The news shook Madinah. 'Umar ibn al-Khattab could not accept it. He stood up and declared that the Prophet ﷺ had not died, but had gone to meet his Lord like Musa, and would return.\nAbu Bakr came from his home at as-Sunh, went in to the Prophet's body, uncovered his face and kissed him, weeping: “How beautiful you are in life and in death.” Then he went out and addressed the people: “Whoever worshipped Muhammad, Muhammad has died. Whoever worships Allah, Allah is Ever-Living and never dies.” He recited Al 'Imran 3:144.\nIt was as if the people had never heard the verse before. 'Umar said his legs gave way and he fell to the ground, realising at last that the Prophet ﷺ had truly passed away."],
 l:[["Ketenangan seorang pemimpin menyelamatkan umat ketika krisis.","A leader's calm saves the community in a crisis."],["Yang disembah ialah Allah, bukan manusia.","Allah alone is worshipped, not any human being."]],
 ay:[{r:"Ali 'Imran 3:144",ar:"وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ ۚ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ",m:["Muhammad hanyalah seorang rasul, yang telah berlalu sebelumnya beberapa rasul. Jika dia wafat atau terbunuh, adakah kamu akan berpaling ke belakang?","Muhammad is only a messenger; messengers have passed away before him. If he dies or is killed, will you turn back on your heels?"]}],
 hd:[{r:"Sahih al-Bukhari 3668",m:["Aisyah (r.a.) meriwayatkan sikap Umar dan ucapan Abu Bakar pada hari kewafatan.","'A'ishah (r.a.) narrated 'Umar's reaction and Abu Bakr's speech on the day of his passing."]}],
 p:["umar","abubakar"],s:"'Umar's Attitude; Abu Bakr's Attitude, p.304|Sikap Umar; Pendirian Abu Bakr"},

{id:"s114",n:114,e:11,y:632.443,ah:11,pl:"madinah",sc:"crescent",
 w:["Selasa hingga malam Rabu, 13 hingga 14 Rabiulawal 11 H","Tuesday to Wednesday night, 13 to 14 Rabi' al-Awwal 11 AH"],
 t:["Pengurusan jenazah & pengebumian","Washing, prayer and burial"],
 f:["Pada hari Isnin itu, para sahabat bermesyuarat di Saqifah Bani Sa'idah dan membai'ah Abu Bakar sebagai khalifah. Pada hari Selasa, jasad Rasulullah ﷺ dimandikan dalam keadaan berpakaian oleh Ali, al-'Abbas dan anak-anaknya al-Fadl dan Qutham, Usamah bin Zaid dan Syuqran. Baginda dikafankan dengan tiga helai kain putih dari Yaman, tanpa baju dan serban.\nMereka berselisih tentang tempat pengebumian. Abu Bakar berkata beliau mendengar Rasulullah ﷺ bersabda bahawa setiap nabi dikebumikan di tempat dia wafat. Maka liang lahad digali di bilik Aisyah. Orang ramai masuk berkumpulan untuk bersolat jenazah secara bersendirian tanpa imam: lelaki, kemudian wanita, kemudian kanak-kanak.\nBaginda dikebumikan pada malam Rabu. Hingga kini, makam Baginda di Masjid an-Nabawi diziarahi jutaan orang yang berselawat ke atasnya.",
   "That Monday the companions met at the hall of Banu Sa'idah and pledged allegiance to Abu Bakr as caliph. On Tuesday the Prophet's ﷺ body was washed, still clothed, by 'Ali, al-'Abbas and his sons al-Fadl and Qutham, Usamah ibn Zayd and Shuqran. He was shrouded in three white Yemeni cloths, with no shirt or turban.\nThey differed over where to bury him. Abu Bakr said he had heard the Prophet ﷺ say that every prophet is buried where he dies. So a grave was dug in 'A'ishah's room. People came in groups to pray over him individually with no imam: men, then women, then children.\nHe was buried on the Wednesday night. To this day his resting place in the Prophet's Masjid is visited by millions who send blessings upon him."],
 l:[["Kesatuan umat dijaga segera selepas kewafatan pemimpin.","The unity of the community was secured right after the leader's passing."],["Kesederhanaan hingga ke saat terakhir.","Simplicity to the very end."]],
 hd:[{r:"Sahih al-Bukhari 1264",m:["Aisyah (r.a.) meriwayatkan Baginda dikafankan dengan tiga helai kain putih tanpa baju dan serban.","'A'ishah (r.a.) narrated that he was shrouded in three white cloths with no shirt or turban."]},{r:"Jami' at-Tirmidhi 1018",m:["Abu Bakar meriwayatkan: “Allah tidak mewafatkan seorang nabi melainkan di tempat yang dia suka dikebumikan.”","Abu Bakr narrated: “Allah does not take a prophet except in the place where he would love to be buried.”"]}],
 p:["ali","abubakar","usamah","aisyah"],s:"Burial and Farewell Preparations to His Honourable Body, p.304|Kafan dan persemadian jasad mulia Baginda ke pembaringan terakhir"}
);
